from result import Ok,Err,UnwrapError,as_result
@as_result(ValueError)
def produce(value):
 if isinstance(value,BaseException):raise value
 return value
normal=produce(3);failure=ValueError('failure');wrapped=produce(failure)
print('decorated_result',normal,wrapped);assert normal==Ok(3) and isinstance(wrapped,Err) and wrapped.err_value is failure
try:produce(TypeError('other'))
except TypeError:pass
else:raise AssertionError('undeclared exception swallowed')

