 actual=glom(value,Iter().all());print('materialized',actual,type(actual).__name__);assert type(actual) is list and actual==value

from glom import M,T,Match,glom
raised=False
try:M('invalid')
except TypeError:raised=True
print('invalid_subspec_rejected',raised);assert raised
actual=glom({'value':3},Match(M(T['value'])==3));print('valid_subspec',actual);assert actual=={'value':3}

